from pathlib import Path

CONTENT = {'library/help/article.txt': [('Library remembers your last reading position in each verified public Library article. Open it again to resume.\r\n', 'Deep32 Encyclopedia remembers your last reading position in each verified public Library article. Open it again to resume.\r\n', 1), ('font patch; until it merges, choose -typesize S, M or L when starting Library.\r\n', 'font patch; until it merges, choose -typesize S, M or L when starting Deep32 Encyclopedia.\r\n', 1)], 'library/screens/main.scr': [('\t\tlabel "Deep32 Library"               # the program\'s name, drawn in capitals\n', '\t\tlabel "DEEP32 ENCYCLOPEDIA"               # the program\'s name, drawn in capitals\n', 1), ('\ton 1545 room.about "About Library"\n', '\ton 1545 room.about "About Deep32 Encyclopedia"\n', 1), ('\t\tlabel "Deep32 Library"\n', '\t\tlabel "Deep32 Encyclopedia"\n', 1)], 'library/screens/settings.scr': [('\t\tlabel "Library Appearance"\n', '\t\tlabel "Deep32 Encyclopedia Appearance"\n', 1), ('\t\tlabel "Library looks"\n', '\t\tlabel "Deep32 Encyclopedia looks"\n', 1), ('\t\tlabel "Use selects. Settings OK saves. Reopen Library to apply."\n', '\t\tlabel "Use selects. Settings OK saves. Reopen Deep32 Encyclopedia to apply."\n', 1)], 'library/screens/title.scr': [('\t\tlabel "Deep32 Library"\r\n', '\t\tlabel "Deep32 Encyclopedia"\r\n', 1)], 'library/src/app/app.c': [('\t                            XmNiconName, "Deep32 Library", NULL);\n', '\t                            XmNiconName, "Deep32 Encyclopedia", NULL);\n', 1), ('\tif (A.vis->class != TrueColor) { fprintf(stderr, "d32library: Deep32 Library needs a TrueColor visual (depth %d)\\n", A.depth); return 1; }\n', '\tif (A.vis->class != TrueColor) { fprintf(stderr, "d32library: Deep32 Encyclopedia needs a TrueColor visual (depth %d)\\n", A.depth); return 1; }\n', 1)], 'library/src/app/article_features.c': [('\t\t\te26j_lit(&q->text, cls && !strcmp(cls, "library") ? "\\nDeep32 Library text (not evidence).\\n\\n" : "\\nCorpus glossary entry.\\n\\n");\n', '\t\t\te26j_lit(&q->text, cls && !strcmp(cls, "library") ? "\\nDeep32 Encyclopedia text (not evidence).\\n\\n" : "\\nCorpus glossary entry.\\n\\n");\n', 1)], 'library/src/app/cite.c': [('\tput(b, "Deep32 Library, generation %s; ", has(c->generation) ? c->generation : "unknown");\r\n', '\tput(b, "Deep32 Encyclopedia, generation %s; ", has(c->generation) ? c->generation : "unknown");\r\n', 1), ('\t\t\tput(&b, "! %s . Deep32 Library, %s . %s%s\\n", has(c->cite) ? c->cite : has(c->id) ? c->id : "",\r\n', '\t\t\tput(&b, "! %s . Deep32 Encyclopedia, %s . %s%s\\n", has(c->cite) ? c->cite : has(c->id) ? c->id : "",\r\n', 1)], 'library/src/app/cite.h': [('#define CITE_TRAILER "Deep32 Library: not verified evidence."\r\n', '#define CITE_TRAILER "Deep32 Encyclopedia: not verified evidence."\r\n', 1)], 'library/src/app/fonts.c': [('\t[READER_ORIGINAL] = { "original", "Library Classic" },\n', '\t[READER_ORIGINAL] = { "original", "Deep32 Encyclopedia Classic" },\n', 1)], 'library/src/app/kind_edit.c': [('\t\tif (a->verbose) fprintf(stderr, "d32library: field %s: pasted %lu bytes%s\\n", p->s->c[p->ctl].id, (unsigned long)n, f->library ? " (Deep32 Library text)" : "");\r\n', '\t\tif (a->verbose) fprintf(stderr, "d32library: field %s: pasted %lu bytes%s\\n", p->s->c[p->ctl].id, (unsigned long)n, f->library ? " (Deep32 Encyclopedia text)" : "");\r\n', 1)], 'library/src/app/nav.c': [('\tsnprintf(t, sizeof t, "Deep32 Library - %s", room);\r\n', '\tsnprintf(t, sizeof t, "Deep32 Encyclopedia - %s", room);\r\n', 1), ('\tsnprintf(text, sizeof text, "%s is coming in a later build of Deep32 Library.", t);\r\n', '\tsnprintf(text, sizeof text, "%s is coming in a later build of Deep32 Encyclopedia.", t);\r\n', 1)], 'library/src/app/room_article.c': [('\tnav_notice_text(a, "Text sizes", "Live text-size changes need the LAYOUT font patch. The -typesize option works when starting Library.");\n', '\tnav_notice_text(a, "Text sizes", "Live text-size changes need the LAYOUT font patch. The -typesize option works when starting Deep32 Encyclopedia.");\n', 1)], 'library/src/app/room_pinpoint.c': [('\t\tsnprintf(F.status, sizeof F.status, "The Library generation changed. Restart Library before searching again.");\n', '\t\tsnprintf(F.status, sizeof F.status, "The Library generation changed. Restart Deep32 Encyclopedia before searching again.");\n', 1), ('\treturn expanded.failure == SECTION_STALE ? "The Library changed. Restart Library to reload sections." :\n', '\treturn expanded.failure == SECTION_STALE ? "The Library changed. Restart Deep32 Encyclopedia to reload sections." :\n', 1)], 'library/src/render/op_pdfwrite.c': [('\t\t\tpdf_dict_put_text_string(ctx, info, PDF_NAME(Creator), "Deep32 Library");\r\n', '\t\t\tpdf_dict_put_text_string(ctx, info, PDF_NAME(Creator), "Deep32 Encyclopedia");\r\n', 1), ('\t\t\tpdf_dict_put_text_string(ctx, info, PDF_NAME(Producer), "Deep32 Library e26-render");\r\n', '\t\t\tpdf_dict_put_text_string(ctx, info, PDF_NAME(Producer), "Deep32 Encyclopedia e26-render");\r\n', 1)]}


def apply(tree_dir):
    root = Path(tree_dir)
    prepared = []
    # Preflight the complete table before writing any target.
    for rel, edits in CONTENT.items():
        path = root / rel
        if not path.is_file() or path.is_symlink():
            raise FileNotFoundError('1010: target missing or linked: ' + rel)
        text = path.read_bytes().decode('utf-8')
        for before, after, want in edits:
            got = text.count(before)
            if got != want:
                raise ValueError('1010: %s: expected %d occurrences, found %d: %r' % (rel, want, got, before))
            text = text.replace(before, after)
        prepared.append((rel, path, text.encode('utf-8')))
    for rel, path, content in prepared:
        path.write_bytes(content)
    return [rel for rel, _, _ in prepared]
